    @Autowired
    private ChatService chatService;
    @Autowired
    private LinkGenerator linkGenerator;
    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Override
    public ChatResponse processQuestion(ChatRequest request) {
        String userQuestion = request.getMessage();
        // 空值校验
        if (StringUtils.isEmpty(userQuestion)) {
            return new ChatResponse(400, "请输入查询内容！");
        }

        try {
            // 优化提示词（添加规则）
            String optimizedQuestion = CATEGORY_TABLE_MAP + "\n用户当前问题：" + userQuestion;

            // 构建API请求
            ChatRequest apiRequest = new ChatRequest();
            apiRequest.setSessionId(request.getSessionId());
            apiRequest.setMessage(optimizedQuestion);
            apiRequest.setHistory(request.getHistory());
            apiRequest.setUserId(request.getUserId());

            // 调用DeepSeek API
            ChatResponse apiResponse = chatService.sendMessage(apiRequest);
            if (apiResponse.getCode() != 200) {
                return new ChatResponse(500, AiAssistantConfig.AI_NAME + "：" + apiResponse.getErrorMsg());
            }

            // 格式化回复（补充链接）
            String formattedAnswer = formatAnswer(apiResponse.getMessage());
            return new ChatResponse(apiRequest.getSessionId(), formattedAnswer);

        } catch (Exception e) {
            return new ChatResponse(500, AiAssistantConfig.AI_NAME + "：查询出错啦！" + e.getMessage());
        }
    }

    // 格式化回复（补全链接路径）
    private String formatAnswer(String answer) {
        answer = answer.replace("(detail/", "(" + linkGenerator.generateLink("detail", "").replace("/detail/", "/detail/"));
        answer = answer.replace("(module/", "(" + linkGenerator.generateLink("big", "").replace("/module/", "/module/"));
        return answer;
    }
